from __future__ import annotations
import base64, io, zipfile, hashlib, logging
from collections import Counter
from collections.abc import Buffer

import mpmath as mp
import numpy as np
import cv2
from PIL import Image

logger = logging.getLogger("ces")


class SteganographyError(ValueError):
    pass


# ============================================================================
# henon.py  (upstream bodies, verbatim; relative imports + typing dropped)
# ============================================================================
mp.mp.dps = 200
K = 48
S = 1 << K
MASK64 = (1 << 64) - 1


def _splitmix64(x: int, /) -> int:
    x = (x + 0x9E3779B97F4A7C15) & MASK64
    x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9 & MASK64
    x = (x ^ (x >> 27)) * 0x94D049BB133111EB & MASK64
    return (x ^ (x >> 31)) & MASK64


def _keyhash64(key) -> int:
    if isinstance(key, Buffer):
        data = bytes(key)
    else:
        data = str(key).encode("utf-8", "surrogatepass")
    return int.from_bytes(hashlib.blake2b(data, digest_size=8).digest(), "little")


def shannon_entropy(seq, /) -> mp.mpf:
    counts = Counter(seq)
    n = mp.mpf(len(seq))
    ln2 = mp.log(2)
    h = mp.mpf("0")
    for c in counts.values():
        p = mp.mpf(c) / n
        h -= p * (mp.log(p) / ln2)
    return h


def _mp_to_fixed(x: mp.mpf, /) -> int:
    return int(mp.nint(x * S))


X0 = _mp_to_fixed(mp.mpf("0.123456789123"))
Y0 = _mp_to_fixed(mp.mpf("0.362436069531"))


def henon_params(key) -> tuple[int, int]:
    ent = shannon_entropy(key)
    a = _mp_to_fixed((mp.mpf("56") - ent) / mp.mpf("40"))
    b = _mp_to_fixed((mp.mpf("24") + ent) / mp.mpf("80"))
    h = _keyhash64(key)
    a += ((h & 0xFFFFFFFF) - 0x80000000) >> 16
    b += (((h >> 32) & 0xFFFFFFFF) - 0x80000000) >> 16
    return a, b


def henon_indices(arr, key, count: int):
    if count < 0:
        raise ValueError("expected count to be non-negative number")

    def generate():
        a, b = henon_params(key)
        x, y = X0, Y0
        n = count
        max_steps = count * 10
        steps = 0
        visited = np.zeros(arr.size, dtype=bool)
        while n > 0 and steps < max_steps:
            steps += 1
            x = S + y - (a * (x**2)) // (S**2)
            y = (b * x) // S
            z = ((x & MASK64) ^ ((y & MASK64) << 1)) & MASK64
            idx = _splitmix64(z ^ _splitmix64(steps)) % arr.size
            if visited[idx]:
                continue
            visited[idx] = True
            yield idx
            n -= 1

    indices = np.fromiter(generate(), dtype=np.int64, count=count)
    d0, d1, d2 = _i_to_yxz(indices, *arr.shape[:2])
    return d0, d1, d2


def _i_to_yxz[_Dim = int](indices, h: int, w: int):
    plane = h * w
    z = indices // plane
    rem = indices - z * plane
    x = rem // h
    y = rem - x * h
    return y, x, z


# ============================================================================
# steg.py  (upstream bodies, verbatim; relative imports + typing dropped)
# ============================================================================
def adaptive_canny(arr, count: int, lo=(45, 85), hi=(135, 255), niter=10, tol=None):
    if arr.dtype != np.uint8:
        raise ValueError("expected uint8")
    if tol is None:
        tol = 1.0 / arr.size
    lmin, lmax = (max(int(x), 0) & 0xFF for x in lo)
    hmin, hmax = (max(int(x), 0) & 0xFF for x in hi)
    target_density = count / arr.size
    target_edge_density = min(max(1.0 - target_density, 0.0), 1.0)
    filtered = cv2.bilateralFilter(arr, d=9, sigmaColor=75, sigmaSpace=75)
    lo_t = 0.0
    hi_t = 1.0
    best_err = best_edges = None
    prev_lower = prev_upper = None
    reason = None
    for _ in range(niter):
        t = (lo_t + hi_t) * 0.5
        lower = int(round(lmin + t * (lmax - lmin)))
        upper = int(round(hmin + t * (hmax - hmin)))
        if lower > upper:
            lower, upper = upper, lower
        if best_edges is not None and (lower, upper) == (prev_lower, prev_upper):
            reason = "thresholds stable"
            break
        prev_lower, prev_upper = lower, upper
        edges = cv2.Canny(filtered, lower, upper)
        edge_density = cv2.countNonZero(edges) / arr.size
        err = abs(edge_density - target_edge_density)
        if best_err is None or err < best_err:
            best_err, best_edges = err, edges
        if err <= tol:
            reason = "tolerance met"
            break
        if edge_density > target_edge_density:
            lo_t = t
        else:
            hi_t = t
    return best_edges


DEFAULT_KEY = "SECRET_PASSWORD"
MAGIC = b"CES"
HEADER_BITS_SIZE = (len(MAGIC) + 4) * 8


def embed(img, payload, key=None):
    if key is None:
        key = DEFAULT_KEY
    header = np.frombuffer(MAGIC + len(payload).to_bytes(4, "little"), dtype=np.uint8)
    header_bits = np.unpackbits(header)
    assert header_bits.size == HEADER_BITS_SIZE
    payload_bits = np.unpackbits(payload)
    img = img.copy()
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    occupied = np.zeros(gray.shape, dtype=bool)
    for bits in [header_bits, payload_bits]:
        count = bits.size
        edges = adaptive_canny(gray, count) & ~occupied
        ys, xs = np.nonzero(edges)
        domain = np.empty((ys.size, 1, 3), dtype=np.uint8)
        try:
            d0, _, d2 = henon_indices(domain, key, count)
        except ValueError as e:
            if "iterator too short" in str(e):
                raise SteganographyError("payload too large for image") from e
            raise
        idx = ys[d0], xs[d0], d2
        img[idx] = (img[idx] & 0xFE) | bits
        occupied[idx[:2]] = True
    return img


def extract(cover_img, carrier_img, key=None):
    if cover_img.shape != carrier_img.shape:
        raise ValueError(
            "shapes do not match: {.shape} and {.shape}".format(cover_img, carrier_img)
        )
    elif np.array_equal(cover_img, carrier_img):
        raise ValueError("cover image and carrier image are identical")
    if key is None:
        key = DEFAULT_KEY
    gray = cv2.cvtColor(cover_img, cv2.COLOR_BGR2GRAY)
    ignored = np.zeros(gray.shape, dtype=bool)

    def get_idx(count: int):
        edges = adaptive_canny(gray, count) & ~ignored
        ys, xs = np.nonzero(edges)
        domain = np.empty((ys.size, 1, 3), dtype=np.uint8)
        d0, _, d2 = henon_indices(domain, key, count)
        return ys[d0], xs[d0], d2

    header_idx = get_idx(HEADER_BITS_SIZE)
    header_bytes = np.packbits(carrier_img[header_idx] & 1).tobytes()
    if header_bytes.startswith(MAGIC):
        header_bytes = header_bytes.removeprefix(MAGIC)
    else:
        raise ValueError("bad password")
    ignored[header_idx[:2]] = True
    payload_len = int.from_bytes(header_bytes, "little")
    idx = get_idx(payload_len * 8)
    return np.packbits(carrier_img[idx] & 1)


# ============================================================================
# glue — PNG <-> BGR, upstream zip container, and the four sheet callables
# ============================================================================
def _b64_to_bgr(s):
    raw = base64.b64decode(s)
    im = Image.open(io.BytesIO(raw)).convert("RGB")
    return cv2.cvtColor(np.array(im, np.uint8), cv2.COLOR_RGB2BGR)


def _bgr_to_png_b64(bgr):
    rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    buf = io.BytesIO()
    Image.fromarray(rgb).save(buf, format="PNG")
    return base64.b64encode(buf.getvalue()).decode("ascii")


def _zip_wrap(data: bytes):
    # upstream collect_zipfile_arr single-stream branch: one member 0.bin,
    # archive comment b"0" (so upstream dump_zipfile_arr unwraps it).
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w") as zf:
        zf.comment = b"0"
        with zf.open("0.bin", "w") as f:
            f.write(data)
    return np.frombuffer(buf.getvalue(), dtype=np.uint8)


def _zip_unwrap(arr) -> bytes:
    buf = io.BytesIO(arr.tobytes())
    try:
        z = zipfile.ZipFile(buf)
        return z.read(z.namelist()[0])
    except Exception:
        return arr.tobytes()


def _key(password):
    return password if password else DEFAULT_KEY


def ces_embed(cover_b64, text, password):
    bgr = _b64_to_bgr(cover_b64)
    payload = _zip_wrap(str(text).encode("utf-8"))
    steg = embed(bgr, payload, key=_key(password))
    return _bgr_to_png_b64(steg)


def _extract_text(cover_bgr, steg_bgr, key):
    payload = extract(cover_bgr, steg_bgr, key=key)
    return _zip_unwrap(payload).decode("utf-8", "replace")


def ces_decode(a_b64, b_b64, password):
    # Non-blind: needs the original cover + the steg image + password.
    # Try A=cover/B=steg; on any failure (bad password / header miss) swap
    # and try B=cover/A=steg. Return recovered text, or "bad password: ..."
    key = _key(password)
    a = _b64_to_bgr(a_b64)
    b = _b64_to_bgr(b_b64)
    try:
        return _extract_text(a, b, key)
    except Exception:
        try:
            return _extract_text(b, a, key)
        except Exception as e2:
            return "bad password / wrong images: " + str(e2)


def ces_checksize(cover_b64):
    raw = base64.b64decode(cover_b64)
    im = Image.open(io.BytesIO(raw))
    w, h = im.size
    md = max(w, h)
    if md > 680:
        return "TOO BIG: %dx%d (max dim %d > 680). X will re-compress to JPEG and destroy the hidden payload. Downscale first." % (w, h, md)
    return "size OK - %dx%d, <=680px" % (w, h)


def ces_downscale(cover_b64, maxdim):
    raw = base64.b64decode(cover_b64)
    im = Image.open(io.BytesIO(raw)).convert("RGB")
    w, h = im.size
    md = max(w, h)
    m = int(maxdim)
    if md > m:
        scale = m / md
        im = im.resize((max(1, round(w * scale)), max(1, round(h * scale))), Image.LANCZOS)
    buf = io.BytesIO()
    im.save(buf, format="PNG")
    return base64.b64encode(buf.getvalue()).decode("ascii")


# ============================================================================
# the single sheet callable — one op-selector dispatcher, minted once by the
# =def binder below. (op is a plain data selector, like fs.command('ls',…);
# no function is resolved from a string — R4-clean.)
# ============================================================================
def ces(op, *args):
    if op == "decode":
        return ces_decode(args[0], args[1], args[2])
    if op == "embed":
        return ces_embed(args[0], args[1], args[2])
    if op == "size":
        return ces_checksize(args[0])
    if op == "downscale":
        return ces_downscale(args[0], int(args[1]))
    return "unknown op: " + str(op)


